_BY_ID = {p["id"]: p for p in DRAFT_PLAYERS}
_BY_POSITION = {}
for _p in DRAFT_PLAYERS:
    _BY_POSITION.setdefault(_p["position"], []).append(_p)


def get_draft_pool_by_position(position: str) -> list:
    return list(_BY_POSITION.get(position, []))


def get_draft_player_by_id(player_id: int):
    return _BY_ID.get(player_id)


def get_all_draft_ids() -> list:
    return list(_BY_ID.keys())
